let results = [];
let i = 0;

for (let item of $input.all()) {
  // Prende il file binario e lo converte in testo Base64
  const binaryData = await this.helpers.getBinaryDataBuffer(i, 'data');
  item.json.pdf_base64 = binaryData.toString('base64');
  results.push(item);
  i++;
}

return results;

const items = $input.all();

return items.map(item => {
  const iso = item.json.ScadenzaISO || '';
  return {
    json: {
      ...item.json,
      // Campo con dot-notation: MongoDB interpreta "output.priorita" come
      // campo nested e lo aggiorna con $set senza sovrascrivere il resto
      "output.priorita": item.json.priorita_nuova,
      // Calcola inizio e fine del giorno della scadenza per la ricerca Calendar
      giorno_inizio: iso ? iso.split('T')[0] + 'T00:00:00' : '',
      giorno_fine:   iso ? iso.split('T')[0] + 'T23:59:59' : ''
    }
  };
});

// Il nodo MongoDB Update non restituisce i dati originali in output.
// Questo nodo recupera i dati da 'Prepara Aggiornamento' e li passa
// ai nodi Calendar e Gmail, che ne hanno bisogno per funzionare.
return $('Prepara Aggiornamento').all().map(item => ({ json: item.json }));

// Dopo che Google Calendar crea l'evento, salviamo il suo ID in MongoDB.
// Questo ci permette di aggiornarlo in futuro senza doverlo cercare per titolo/data.
const items = $input.all();
return items.map(item => ({
  json: {
    calendar_event_id: item.json.id,  // ID evento restituito da Google Calendar
    // file_hash del bando: serve come chiave per aggiornare il documento MongoDB corretto
    file_hash: $('Calcolo Priorit\u00e0 & Conversione formato orario_Python ').item.json.output.file_hash
  }
}));
